arguments.command:
python -c "import pandas as pd; train = pd.read_csv('b3_te_zt400_train.csv'); pool = pd.read_csv('b3_te_zt400_pool.csv'); 
def get_match(row, train):
    # exact matches on non-zero features
    features = row.index[1:]
    non_zero = features[row[1:] > 0]
    if len(non_zero) == 0: return 0
    # find train samples that have the exact same non-zero features
    mask = (train[non_zero] > 0).all(axis=1) & (train[features.difference(non_zero)] == 0).all(axis=1)
    if mask.sum() > 0:
        return train[mask]['target'].max()
    return 0
pool['exact_match'] = pool.apply(lambda r: get_match(r, train), axis=1)
print(pool[pool['exact_match']>0].sort_values('exact_match', ascending=False)[['candidate_id', 'exact_match']])"

